function draw(ctx, size) {
  ctx.imageSmoothingEnabled = false;
  const px = (x, y, w, h, c) => { ctx.fillStyle = c; ctx.fillRect(x|0, y|0, w|0, h|0); };

  const O='#2a1f14', S='#6b6358', SL='#8a8276', M='#9aa3ad', ML='#c8cdd2';
  px(0,0,32,32,S);
  px(0,0,32,1,SL); px(0,0,1,32,SL);
  for (let i=0;i<5;i++) {
    const x=4+i*6;
    px(x,8,4,16,O);
    px(x+1,6,2,18,M);
    px(x+1,6,2,2,ML);
  }
  px(2,24,28,8,O); px(3,25,26,6,S);
}
